1886	// lookupGitHubRepoSize asks the GitHub REST API for the size of the source
1887	// repository. It reports false when the source is not a GitHub repository
1888	// reached over HTTP, in which case no request was made.
1889	//
1890	// The source credentials go along: GitHub answers 404 to an anonymous caller
1891	// for a private repository, and the anonymous rate limit (60 requests an hour,
1892	// shared by everything behind the same egress IP) fails public lookups too.
1893	// They are sent only to the GitHub API, for a repository the user pointed at
1894	// github.com on its default port (see GitHubOwnerRepo), and a redirect that
1895	// leaves the API host drops them. A token the API refuses although git
1896	// accepted it (one not authorized for an organization's SSO, say) is retried
1897	// once anonymously, so a public repository is never worse off than before
1898	// credentials were sent.
1899	func lookupGitHubRepoSize(ctx context.Context, conn gitproto.Conn) (githubSizeLookup, bool) {
1900		httpConn, ok := conn.(*gitproto.HTTPConn)
1901		if !ok || httpConn.HTTP == nil {
1902			return githubSizeLookup{}, false
1903		}
1904		owner, repo, ok := GitHubOwnerRepo(conn)
1905		if !ok {
1906			return githubSizeLookup{}, false
1907		}
1908		ctx, cancel := context.WithTimeout(ctx, githubPreflightTimeout)
1909		defer cancel()
1910		lookup := githubSizeLookup{owner: owner, repo: repo}
1911		if creds := sourceCredentials(httpConn); creds != nil {
1912			lookup.authenticated = true
1913			requestGitHubRepoSize(ctx, httpConn, creds, &lookup)
1914			if lookup.status != http.StatusUnauthorized && lookup.status != http.StatusForbidden {
1915				return lookup, true
1916			}
1917			lookup = githubSizeLookup{owner: owner, repo: repo, refusedAuthStatus: lookup.status}
1918		}
1919		requestGitHubRepoSize(ctx, httpConn, nil, &lookup)
1920		return lookup, true
1921	}
