1982	// githubAPIError describes a non-200 answer, carrying GitHub's own message
1983	// ("Not Found", "API rate limit exceeded ...") when the body has one. The
1984	// message is server-authored, so it is stripped of control characters and
1985	// bounded before it reaches a log or a terminal.
1986	func githubAPIError(status int, body io.Reader) error {
1987		var payload struct {
1988			Message string `json:"message"`
1989		}
1990		if err := json.NewDecoder(body).Decode(&payload); err != nil || payload.Message == "" {
1991			return fmt.Errorf("github api returned %d", status)
1992		}
1993		msg := strings.Join(strings.Fields(sanitize.Text(payload.Message)), " ")
1994		if len(msg) > maxGitHubErrorMessageBytes {
1995			msg = strings.ToValidUTF8(msg[:maxGitHubErrorMessageBytes], "") + "..."
1996		}
1997		return fmt.Errorf("github api returned %d: %s", status, msg)
1998	}
