// httpClientFor returns the HTTP client for one sync. github-kind syncs
// share the long-lived client (target rides mTLS, github.com rides the
// public-CA base). An entiredb-kind sync gets a per-sync client whose
// cluster set additionally trusts the consume-time admitted source cluster
// parent — so the fetch, and the per-node hosts the source cluster's
// /info/refs 307s to, present the client cert (the whole credential: the
// source's svctok listener grants the workload cert-only cluster-wide pull).
// The raw SourceURL never expands this trust set. With no mTLS transport
// configured (dev/loadtest single-URL setups) the per-sync client degrades to
// the shared public base exactly like target pushes do.
func (s *syncer) httpClientFor(req syncRequest) *http.Client {
	if !req.entiredbSourced() {
		return s.httpClient
	}
	clusters := append([]string{req.SourceClusterParent}, s.targetClusters...)
	// The source's svctok host is an entry host for this sync: its
	// /info/refs 307s off non-hosting nodes exactly like the target's, and
	// its replica set is cached under its own key. Admission has already
	// validated SourceURL's shape, so a parse failure here just leaves the
	// source uncached rather than failing the sync.
	entryHosts := s.entryHosts
	if h, err := entryHostPort(req.SourceURL); err == nil {
		entryHosts = append([]string{h}, s.entryHosts...)
	}
	var rt http.RoundTripper = &clusterTransport{
		clusters:    clusters,
		entryHosts:  entryHosts,
		base:        s.publicBase,
		clusterBase: s.clusterBase,
		replicas:    s.replicas,
		metrics:     s.metrics,
	}
	if req.namespaceScoped() {
		rt = &syncKindTransport{base: rt, kind: syncKindNamespace, clusters: s.targetClusters}
	}
	return &http.Client{Transport: rt}
}

// entryHostPort returns the host:port of a cluster entry URL exactly as it
// appears in the URLs git-sync builds from it (url.URL.Host), which is what
// clusterTransport.entryHosts is matched against.
func entryHostPort(rawURL string) (string, error) {
	u, err := url.Parse(rawURL)
	if err != nil {
		return "", fmt.Errorf("parse entry URL %q: %w", rawURL, err)
	}
	if u.Hostname() == "" {
		return "", fmt.Errorf("entry URL %q has no host", rawURL)
	}
	return u.Host, nil
}

