// sourceAuth returns a gitsync.AuthProvider for the source endpoint.
// entiredb sources never mint: the worker's client certificate is the whole
// credential (the source cluster's svctok listener grants the workload
// cert-only cluster-wide pull), and clusterTransport already routes the
// fetch onto the mTLS round-tripper — a nil provider attaches no header.
// For GitHub, returns nil when the job has no installation ID or the App
// client is not configured — callers fall through to anonymous GitHub
// access for public repos.
func (s *syncer) sourceAuth(ctx context.Context, req syncRequest) (gitsync.AuthProvider, error) {
	if req.entiredbSourced() {
		return nil, nil
	}
	if req.InstallationID == 0 || s.githubApp == nil {
		return nil, nil
	}

	ctx, span := Tracer().Start(ctx, "mirror.source_auth",
		trace.WithAttributes(
			attribute.Int64("entire.installation_id", req.InstallationID),
			attribute.String("entire.source_repo", req.SourceRepo),
		),
	)
	defer span.End()

	// Time exactly the mint round-trip. This is the most actionable git-op
	// breakdown leg (a synchronous entire-core STS call on every authenticated
	// sync) and the before/after baseline for COR-596 token caching. Tagged
	// ok|error only — the failure breakdown lives on this span, not the metric.
	start := time.Now()
	token, err := s.githubApp.InstallationToken(ctx, req.TargetULID, req.SourceOwner, req.SourceRepo, req.InstallationID)
	if err != nil {
		s.metrics.recordSourceAuth(ctx, sourceAuthOutcomeError, time.Since(start))
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "installation token")
		// Returned unwrapped exactly as before: the sole caller (sync) wraps it
		// with "resolving source auth: %w" and runs it through classifySyncError,
		// and the token-leak guard (TestSyncDoesNotLeakInstallationToken) depends
		// on that path — re-wrapping here would change the error text under it for
		// no benefit.
		return nil, err
	}
	s.metrics.recordSourceAuth(ctx, sourceAuthOutcomeOK, time.Since(start))
	return gitsync.StaticAuthProvider{
		Source: gitsync.EndpointAuth{Username: "x-access-token", Token: token},
	}, nil
}

